import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, nowIso, rowToJob, type JobRow } from './db.ts';

const MAX_BODY_BYTES = 1024 * 1024;
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const HEARTBEAT_FRESH_MS = 3000;
const SHUTDOWN_TIMEOUT_MS = 3000;

interface FieldError {
  field: string;
  message: string;
}

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields !== undefined) error.fields = fields;
  send(res, status, { error });
}

function sendInvalid(res: ServerResponse, fields: FieldError[]): void {
  sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
}

function sendMethodNotAllowed(res: ServerResponse, allow: string): void {
  res.setHeader('allow', allow);
  sendError(res, 405, 'method_not_allowed', 'Method not allowed for this path.');
}

/** Reads the whole body. Returns null when it exceeds MAX_BODY_BYTES. */
async function readBody(req: IncomingMessage): Promise<string | null> {
  const chunks: Buffer[] = [];
  let size = 0;
  let tooLarge = false;
  for await (const chunk of req) {
    const buf = chunk as Buffer;
    size += buf.length;
    if (size > MAX_BODY_BYTES) {
      tooLarge = true;
      continue;
    }
    chunks.push(buf);
  }
  return tooLarge ? null : Buffer.concat(chunks).toString('utf8');
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

/** Reads an optional integer field, recording a field error if it is out of range or not a number. */
function integerField(body: Record<string, unknown>, name: string, min: number, max: number, dflt: number, fields: FieldError[]): number {
  if (!Object.hasOwn(body, name)) return dflt;
  const v = body[name];
  if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
    fields.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return dflt;
  }
  return v;
}

interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

/** Validates a POST /api/jobs request. Returns the job on success, or the list of field errors. */
async function parseCreateRequest(
  req: IncomingMessage,
  fields: FieldError[],
): Promise<{ job: NewJob; idempotencyKey: string | null } | { fields: FieldError[] }> {
  let idempotencyKey: string | null = null;
  const keyHeader = req.headers['idempotency-key'];
  if (keyHeader !== undefined) {
    const key = Array.isArray(keyHeader) ? keyHeader.join(',') : keyHeader;
    if (IDEMPOTENCY_KEY_RE.test(key)) idempotencyKey = key;
    else fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  const mediaType = (req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
    return { fields };
  }

  const raw = await readBody(req);
  if (raw === null) {
    fields.push({ field: 'body', message: `body must not exceed ${MAX_BODY_BYTES} bytes` });
    return { fields };
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    fields.push({ field: 'body', message: 'body must be valid JSON' });
    return { fields };
  }
  if (!isPlainObject(parsed)) {
    fields.push({ field: 'body', message: 'body must be a JSON object' });
    return { fields };
  }

  for (const key of Object.keys(parsed)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }

  let input = '';
  if (!Object.hasOwn(parsed, 'input')) {
    fields.push({ field: 'input', message: 'is required' });
  } else {
    const v = parsed.input;
    if (typeof v !== 'string' || v.length < 1 || v.length > 1000 || v.trim() === '') {
      fields.push({ field: 'input', message: 'must be a string of 1 to 1000 characters that is not only whitespace' });
    } else {
      input = v;
    }
  }

  const steps = integerField(parsed, 'steps', 1, 20, 5, fields);
  const failAttempts = integerField(parsed, 'failAttempts', 0, 5, 0, fields);

  if (fields.length > 0) return { fields };
  return { job: { input, steps, failAttempts }, idempotencyKey };
}

type CreateOutcome = { existing: true; row: JobRow } | { existing: false; row: JobRow };

/** Inserts the job, or returns the existing row for the same idempotency key. One short IMMEDIATE transaction. */
function insertOrFindByKey(job: NewJob, payload: string, idempotencyKey: string | null): CreateOutcome {
  db.exec('BEGIN IMMEDIATE');
  try {
    if (idempotencyKey !== null) {
      const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(idempotencyKey) as JobRow | undefined;
      if (existing) {
        db.exec('COMMIT');
        return { existing: true, row: existing };
      }
    }
    const id = randomUUID();
    const now = nowIso();
    db.prepare(
      `INSERT INTO jobs(id, status, input, steps, fail_attempts, attempts, progress_completed,
         result_output, error, idempotency_key, payload, run_after, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, 0, ?, ?)`,
    ).run(id, job.input, job.steps, job.failAttempts, idempotencyKey, payload, now, now);
    const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow;
    db.exec('COMMIT');
    return { existing: false, row };
  } catch (e) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // no transaction was open
    }
    throw e;
  }
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const result = await parseCreateRequest(req, []);
  if ('fields' in result) {
    sendInvalid(res, result.fields);
    return;
  }
  const { job, idempotencyKey } = result;
  // Canonical payload after defaults, in fixed key order, used to compare idempotent replays.
  const payload = JSON.stringify({ input: job.input, steps: job.steps, failAttempts: job.failAttempts });
  const outcome = insertOrFindByKey(job, payload, idempotencyKey);
  if (!outcome.existing) {
    send(res, 201, rowToJob(outcome.row));
    return;
  }
  if (outcome.row.payload === payload) {
    send(res, 200, rowToJob(outcome.row));
    return;
  }
  sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
}

function handleList(res: ServerResponse): void {
  const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
  send(res, 200, { jobs: rows.map(rowToJob) });
}

function handleGet(res: ServerResponse, rawId: string): void {
  let id: string;
  try {
    id = decodeURIComponent(rawId);
  } catch {
    sendError(res, 404, 'not_found', 'Job not found.');
    return;
  }
  const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
  if (!row) {
    sendError(res, 404, 'not_found', 'Job not found.');
    return;
  }
  send(res, 200, rowToJob(row));
}

function handleHealth(res: ServerResponse): void {
  const hb = db.prepare('SELECT beat_at FROM worker_heartbeat WHERE id = 1').get() as { beat_at: number } | undefined;
  const up = hb !== undefined && Date.now() - Number(hb.beat_at) < HEARTBEAT_FRESH_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/') {
    if (method !== 'GET') return sendMethodNotAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/health') {
    if (method !== 'GET') return sendMethodNotAllowed(res, 'GET');
    return handleHealth(res);
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return handleList(res);
    if (method === 'POST') return handleCreate(req, res);
    return sendMethodNotAllowed(res, 'GET, POST');
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return sendMethodNotAllowed(res, 'GET');
    return handleGet(res, match[1]!);
  }
  sendError(res, 404, 'not_found', 'Not found.');
}

const server = createServer((req, res) => {
  route(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (res.headersSent) {
      res.end();
    } else {
      sendError(res, 500, 'internal_error', 'Internal server error.');
    }
  });
});

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  setTimeout(() => process.exit(1), SHUTDOWN_TIMEOUT_MS);
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

