import { setInterval, clearInterval } from 'node:timers';
import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, nowIso, type JobRow } from './db.ts';

const STEP_MS = 100;
const IDLE_POLL_MS = 200;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;
const HEARTBEAT_INTERVAL_MS = 1000;
const SHUTDOWN_TIMEOUT_MS = 3000;

const db = openDatabase();
let stopping = false;

const writeHeartbeat = (): void => {
  try {
    db.prepare(
      'INSERT INTO worker_heartbeat(id, beat_at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET beat_at = excluded.beat_at',
    ).run(Date.now());
  } catch (err) {
    console.error('heartbeat failed:', err);
  }
};
writeHeartbeat();
const heartbeat = setInterval(writeHeartbeat, HEARTBEAT_INTERVAL_MS);

// Any job still marked running belongs to a worker that died. Only one worker runs at a time, so
// it is safe to requeue them. The interrupted attempt is redone, so its count is undone.
db.prepare(
  `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0,
     run_after = 0, updated_at = ? WHERE status = 'running'`,
).run(nowIso());

const claimStmt = db.prepare(
  `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ?
   WHERE seq = (SELECT seq FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1)
   RETURNING *`,
);

function requeue(job: JobRow, attemptsDelta: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', attempts = MAX(attempts + ?, 0), progress_completed = 0,
       run_after = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
  ).run(attemptsDelta, Date.now() + (attemptsDelta === 0 ? RETRY_DELAY_MS : 0), nowIso(), job.id);
}

/** Runs one attempt of a claimed job. `job.attempts` already includes this attempt. */
async function processAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  if (attempt <= job.fail_attempts) {
    // Simulated transient failure at the first step, before any progress.
    await sleep(STEP_MS);
    if (attempt < MAX_ATTEMPTS) {
      requeue(job, 0);
    } else {
      db.prepare(
        `UPDATE jobs SET status = 'failed', error = 'transient failure', result_output = NULL,
           progress_completed = 0, updated_at = ? WHERE id = ? AND status = 'running'`,
      ).run(nowIso(), job.id);
    }
    return;
  }

  const progressStmt = db.prepare(
    `UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
  );
  for (let i = 1; i <= job.steps; i++) {
    if (stopping) {
      // Shutting down mid-job: give the attempt back so it is redone from the start later.
      requeue(job, -1);
      return;
    }
    await sleep(STEP_MS);
    progressStmt.run(i, nowIso(), job.id);
  }

  db.prepare(
    `UPDATE jobs SET status = 'completed', result_output = ?, progress_completed = steps, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(job.input.toUpperCase(), nowIso(), job.id);
}

async function loop(): Promise<void> {
  while (!stopping) {
    try {
      const job = claimStmt.get(nowIso(), Date.now()) as unknown as JobRow | undefined;
      if (job === undefined) {
        await sleep(IDLE_POLL_MS);
        continue;
      }
      await processAttempt(job);
    } catch (err) {
      console.error('worker iteration failed:', err);
      await sleep(IDLE_POLL_MS);
    }
  }
}

function shutdown(): void {
  if (stopping) return;
  stopping = true;
  setTimeout(() => process.exit(1), SHUTDOWN_TIMEOUT_MS);
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

console.log('worker started');
await loop();

clearInterval(heartbeat);
try {
  db.prepare('DELETE FROM worker_heartbeat').run();
} catch {
  // the server will see the heartbeat go stale anyway
}
db.close();
process.exit(0);

